#include <iostream>
#include <fstream>
#include <string>
using namespace std;

string deszyfruj(string s, int k) {
    string wynik = "";
    for (char c : s) {
        wynik += (char)((c - 'A' - k + 26) % 26 + 'A');
    }
    return wynik;
}

int countE(string s) {
    int cnt = 0;
    for (char c : s)
        if (c == 'E') cnt++;
    return cnt;
}

int main() {
    ifstream plik("szyfrogramy.txt");
    string napis;

    while (plik >> napis) {
        int bestK = 0;
        int bestE = -1;
        string bestTekst = "";

        for (int k = 0; k < 26; k++) {
            string odsz = deszyfruj(napis, k);
            int e = countE(odsz);
            if (e > bestE) {
                bestE = e;
                bestK = k;
                bestTekst = odsz;
            }
        }

        cout << napis << ": klucz=" << bestK
             << ", odszyfrowane: " << bestTekst << endl;
    }
    return 0;
}
```

